insert into problem_versions (id, family_id, slug, version, variant, category, difficulty, est_minutes, title, public_payload, provenance, content_hash) values ('community.food-bank@1-with-constraint', 'community.food-bank', 'food-bank-boxes', '1', 'with-constraint', 'community', 'moderate', '6', 'Food bank box allocation', '{"summary":"Match four households to the food boxes in stock while respecting dietary needs.","statement":"A fictional neighbourhood food bank has five boxes left at the end of the day and four households waiting. Give each household exactly one box. Use only what is in stock, and respect every household''s listed needs. If more than one allocation works, any valid allocation is accepted.","facts":["Household 1 (the Okafors) has no dietary restrictions.","Household 2 (the Lindqvists) includes a child with a severe nut allergy.","Household 3 (the Prasads) is vegetarian.","Household 4 (the Moreaus) must avoid gluten for medical reasons."],"fact_table":{"caption":"Boxes in stock (fictional)","columns":["Box","In stock","Contains meat","Contains nuts","Contains gluten"],"rows":[["Standard","2","Yes","Yes","Yes"],["Vegetarian","1","No","Yes","Yes"],["Nut-free","1","Yes","No","Yes"],["Gluten-free","1","No","No","No"]]},"constraints":[{"id":"ONE-BOX-EACH","text":"Each household receives exactly one box.","kind":"rule"},{"id":"STOCK","text":"Do not hand out more boxes of a type than are in stock.","kind":"rule"},{"id":"NUT-ALLERGY","text":"Household 2 must receive a box that contains no nuts.","kind":"practical"},{"id":"VEGETARIAN","text":"Household 3 must receive a box with no meat.","kind":"rule"},{"id":"GLUTEN-FREE","text":"Household 4 must receive a box with no gluten.","kind":"rule"}],"answer_format":{"kind":"choice_fields","instructions":"Choose a box for each household.","fields":[{"id":"h1","label":"Household 1 (Okafor)","options":[{"id":"standard","label":"Standard"},{"id":"vegetarian","label":"Vegetarian"},{"id":"nutfree","label":"Nut-free"},{"id":"glutenfree","label":"Gluten-free"}]},{"id":"h2","label":"Household 2 (Lindqvist)","options":[{"id":"standard","label":"Standard"},{"id":"vegetarian","label":"Vegetarian"},{"id":"nutfree","label":"Nut-free"},{"id":"glutenfree","label":"Gluten-free"}]},{"id":"h3","label":"Household 3 (Prasad)","options":[{"id":"standard","label":"Standard"},{"id":"vegetarian","label":"Vegetarian"},{"id":"nutfree","label":"Nut-free"},{"id":"glutenfree","label":"Gluten-free"}]},{"id":"h4","label":"Household 4 (Moreau)","options":[{"id":"standard","label":"Standard"},{"id":"vegetarian","label":"Vegetarian"},{"id":"nutfree","label":"Nut-free"},{"id":"glutenfree","label":"Gluten-free"}]}]},"explanation_prompt":"Which household did you allocate first and why? What would you do if one more household arrived?"}'::jsonb, '{"author":"Reasoning Lab project team","created":"2026-10-16","license":"MIT","origin":"original","fictional_data":true,"contamination_note":"Original fictional data; not published"}'::jsonb, '6a874e359afbb03de608f5dde95de0983f2fc1f4d1e1fdea24a1cbae020864d8') on conflict (id) do nothing;
insert into problem_keys (problem_version_id, validator, validator_version, rubric, rubric_version, reviewed_explanation, review, reference_output) values ('community.food-bank@1-with-constraint', '{"engine":"rules","attributes":{"standard":{"stock":2,"meat":true,"nuts":true,"gluten":true},"vegetarian":{"stock":1,"meat":false,"nuts":true,"gluten":true},"nutfree":{"stock":1,"meat":true,"nuts":false,"gluten":true},"glutenfree":{"stock":1,"meat":false,"nuts":false,"gluten":false}},"rules":[{"type":"all_fields_answered","constraint_id":"ONE-BOX-EACH"},{"type":"count_value_at_most","constraint_id":"STOCK","value":"standard","max":2},{"type":"count_value_at_most","constraint_id":"STOCK","value":"vegetarian","max":1},{"type":"count_value_at_most","constraint_id":"STOCK","value":"nutfree","max":1},{"type":"count_value_at_most","constraint_id":"STOCK","value":"glutenfree","max":1},{"type":"field_attr","constraint_id":"NUT-ALLERGY","field":"h2","attr":"nuts","op":"eq","value":false},{"type":"field_attr","constraint_id":"VEGETARIAN","field":"h3","attr":"meat","op":"eq","value":false},{"type":"field_attr","constraint_id":"GLUTEN-FREE","field":"h4","attr":"gluten","op":"eq","value":false}],"expected_solutions":[{"fields":{"h1":"standard","h2":"nutfree","h3":"vegetarian","h4":"glutenfree"}}],"fact_table_binding":{"label_column":0,"columns":{"stock":1,"meat":2,"nuts":3,"gluten":4}},"preferences":["Keeping a spare box type flexible for later arrivals is reasonable but not graded."]}'::jsonb, 'community.food-bank@1-with-constraint/v1', '{"version":"rubric-2026-10-a","dimensions":["constraints","alternatives","assumptions","trade_offs"],"constraint_cues":{"ONE-BOX-EACH":["one box","each household","every household"],"STOCK":["stock","only one","only 1","left","run out","available","supply"],"NUT-ALLERGY":["nut","allergy","allergic","lindqvist","household 2"],"VEGETARIAN":["vegetarian","no meat","prasad","household 3"],"GLUTEN-FREE":["gluten","moreau","household 4"]},"edge_case_cues":["another household","one more","extra household","spare","if someone else"],"trade_off_cues":["instead","could also","either","flexib","save the"],"anchors":{}}'::jsonb, 'rubric-2026-10-a', '{"text":"Household 4 can only take the gluten-free box, so it is used. Household 3 then needs a meat-free box that is not gluten-free: the vegetarian box. Household 2 needs a nut-free box; with the gluten-free box gone, that is the nut-free box. Household 1 takes a standard box. This is the only valid allocation, and one standard box is left over.","accepted_summary":"Okafor Standard, Lindqvist Nut-free, Prasad Vegetarian, Moreau Gluten-free (unique)."}'::jsonb, '{"author_checked":true,"independent_review":{"status":"pending","reviewer":null,"date":null},"notes":"Matched variants differ only in the nut-allergy fact and requirement."}'::jsonb, '{"final_answer":{"fields":{"h1":"standard","h2":"nutfree","h3":"vegetarian","h4":"glutenfree"}},"concise_explanation":"Household 4 needs no gluten, so it gets the only gluten-free box. Household 3 is vegetarian, so it gets the vegetarian box. Household 2 has a nut allergy, so it gets the nut-free box. Household 1 gets a standard box.","stated_alternatives":[],"stated_assumptions":["Boxes are not split between households."],"cited_constraint_ids":["GLUTEN-FREE","VEGETARIAN","NUT-ALLERGY","STOCK","ONE-BOX-EACH"],"uncertainty_notes":"One standard box remains for any later arrival."}'::jsonb) on conflict (problem_version_id) do nothing;
