an"},{"id":"nutfree","label":"Nut-free"},{"id":"glutenfree","label":"Gluten-free"}]},{"id":"h3","label":"Household 3 (Prasad)","options":[{"id":"standard","label":"Standard"},{"id":"vegetarian","label":"Vegetarian"},{"id":"nutfree","label":"Nut-free"},{"id":"glutenfree","label":"Gluten-free"}]},{"id":"h4","label":"Household 4 (Moreau)","options":[{"id":"standard","label":"Standard"},{"id":"vegetarian","label":"Vegetarian"},{"id":"nutfree","label":"Nut-free"},{"id":"glutenfree","label":"Gluten-free"}]}]},"explanation_prompt":"Which household did you allocate first and why? What would you do if one more household arrived?"}'::jsonb, '{"author":"Reasoning Lab project team","created":"2026-10-16","license":"MIT","origin":"original","fictional_data":true,"contamination_note":"Original fictional data; not published"}'::jsonb, 'e67685b84e0d45eb192b16e098027f12de4b3d95717b8f99f7098c62c64edd39') on conflict (id) do nothing;
insert into problem_keys (problem_version_id, validator, validator_version, rubric, rubric_version, reviewed_explanation, review, reference_output) values ('community.food-bank@1-without-constraint', '{"engine":"rules","attributes":{"standard":{"stock":2,"meat":true,"nuts":true,"gluten":true},"vegetarian":{"stock":1,"meat":false,"nuts":true,"gluten":true},"nutfree":{"stock":1,"meat":true,"nuts":false,"gluten":true},"glutenfree":{"stock":1,"meat":false,"nuts":false,"gluten":false}},"rules":[{"type":"all_fields_answered","constraint_id":"ONE-BOX-EACH"},{"type":"count_value_at_most","constraint_id":"STOCK","value":"standard","max":2},{"type":"count_value_at_most","constraint_id":"STOCK","value":"vegetarian","max":1},{"type":"count_value_at_most","constraint_id":"STOCK","value":"nutfree","max":1},{"type":"count_value_at_most","constraint_id":"STOCK","value":"glutenfree","max":1},{"type":"field_attr","constraint_id":"VEGETARIAN","field":"h3","attr":"meat","op":"eq","value":false},{"type":"field_attr","constraint_id":"GLUTEN-FREE","field":"h4","attr":"gluten","op":"eq","value":false}],"expected_solutions":[{"fields":{"h1":"standard","h2":"standard","h3":"vegetarian","h4":"glutenfree"}},{"fields":{"h1":"standard","h2":"nutfree","h3":"vegetarian","h4":"glutenfree"}},{"fields":{"h1":"nutfree","h2":"standard","h3":"vegetarian","h4":"glutenfree"}}],"fact_table_binding":{"label_column":0,"columns":{"stock":1,"meat":2,"nuts":3,"gluten":4}},"preferences":["Keeping a spare box type flexible for later arrivals is reasonable but not graded."]}'::jsonb, 'community.food-bank@1-without-constraint/v1', '{"version":"rubric-2026-10-a","dimensions":["constraints","alternatives","assumptions","trade_offs"],"constraint_cues":{"ONE-BOX-EACH":["one box","each household","every household"],"STOCK":["stock","only one","only 1","left","run out","available","supply"],"VEGETARIAN":["vegetarian","no meat","prasad","household 3"],"GLUTEN-FREE":["gluten","moreau","household 4"]},"edge_case_cues":["another household","one more","extra household","spare","if someone else"],"trade_off_cues":["instead","could also","either","flexib","save the"],"anchors":{}}'::jsonb, 'rubric-2026-10-a', '{"text":"Household 4 can only take the gluten-free box, and household 3 then needs the vegetarian box. Households 1 and 2 have no listed restrictions, so they can take any two of the remaining standard, standard, and nut-free boxes. Three allocations are valid.","accepted_summary":"Moreau Gluten-free, Prasad Vegetarian; Okafor and Lindqvist take two of Standard, Standard, Nut-free."}'::jsonb, '{"author_checked":true,"independent_review":{"status":"pending","reviewer":null,"date":null},"notes":"Matched variants differ only in the nut-allergy fact and requirement."}'::jsonb, '{"final_answer":{"fields":{"h1":"standard","h2":"standard","h3":"vegetarian","h4":"glutenfree"}},"concise_explanation":"Household 4 must avoid gluten, so it gets the gluten-free box. Household 3 is vegetarian and gets the vegetarian box. Households 1 and 2 have no restrictions and get the two standard boxes.","stated_alternatives":["Either household 1 or 2 could take the nut-free box instead."],"stated_assumptions":[],"cited_constraint_ids":["GLUTEN-FREE","VEGETARIAN","STOCK","ONE-BOX-EACH"],"uncertainty_notes":"Keeping the nut-free box spare may help a later arrival."}'::jsonb) on conflict (problem_version_id) do nothing;
insert into problem_versions (id, family_id, slug, version, variant, category, difficulty, est_minutes, title, public_payload, provenance, content_hash) values ('community.library-inclusion@1-with-constraint', 'community.library-inclusion', 'library-digital-inclusion', '1', 'with-constraint', 'community', 'moderate', '8', 'Library digital-inclusion plan', '{"summary":"Pick two programmes for a library''s small technology grant while meeting residents'' needs.","statement":"The fictional Cedar Falls branch library has a $3,000 grant to improve digital access this year. It can run exactly two of the five proposed programmes below. Choose two that together meet every requirement. If several pairs qualify, any qualifying pair is accepted; explain the trade-offs you considered.","facts":["A resident survey found that about 40% of households speak Spanish or Vietnamese at home.","The same survey found that about 1 in 5 households has no home internet connection.","Costs are for one year and cannot be split or partly funded."],"fact_table":{"caption":"Proposed programmes (fictional)","columns":["Programme","Cost","Usable without home internet","Support in Spanish or Vietnamese"],"rows":[["Mobile hotspot lending (10 devices)","$1,800","Yes","No"],["Evening laptop class with interpreters","$900","Yes","Yes"],["E-book platform upgrade","$1,500","No","Yes"],["Two new public computers","$2,200","Yes","No"],["App-based reminder service","$400","No","Yes"]]},"constraints":[{"id":"TWO-PROGRAMMES","text":"Choose exactly two programmes.","kind":"rule"},{"id":"BUDGET","text":"The total cost must be $3,000 or less.","kind":"rule"},{"id":"LANGUAGE","text":"At least one chosen programme must offer support in Spanish or Vietnamese.","kind":"rule"},{"id":"NO-HOME-INTERNET","text":"At least one chosen programme must be usable by residents without home internet.","kind":"practical"}],"answer_format":{"kind":"multi_select","instructions":"Select exactly two programmes.","min":2,"max":2,"options":[{"id":"hotspots","label":"Mobile hotspot lending (10 devices)"},{"id":"laptop-class","label":"Evening laptop class with interpreters"},{"id":"ebooks","label":"E-book platform upgrade"},{"id":"computers","label":"Two new public computers"},{"id":"reminders","label":"App-based reminder service"}]},"explanation_prompt":"Which residents does your plan serve best, and who might it still miss?"}'::jsonb, '{"author":"Reasoning Lab project team","created":"2026-10-16","license":"MIT","origin":"original","fictional_data":true,"contamination_note":"Original fictional data; not published before 2026-10-16."}'::jsonb, '88c02afb75cd39931fc38fb27ce23000dec82e79d5b20cb06ae8e4073c79945a') on conflict (id) do nothing;
insert into problem_keys (problem_version_id, validator, validator_version, rubric, rubric_version, reviewed_explanation, review, reference_output) values ('community.library-inclusion@1-with-constraint', '{"engine":"rules","attributes":{"hotspots":{"cost":1800,"offline":true,"multilingual":false},"laptop-class":{"cost":900,"offline":true,"multilingual":true},"ebooks":{"cost":1500,"offline":false,"multilingual":true},"computers":{"cost":2200,"offline":true,"multilingual":false},"reminders":{"cost":400,"offline":false,"multilingual":true}},"rules":[{"type":"selected_count","constraint_id":"TWO-PROGRAMMES","min":2,"max":2},{"type":"selected_sum_at_most","constraint_id":"BUDGET","attr":"cost","max":3000},{"type":"selected_any","constraint_id":"LANGUAGE","attr":"multilingual","equals":true},{"type":"selected_any","constraint_id":"NO-HOME-INTERNET","attr":"offline","equals":true}],"expected_solutions":[{"selected":["hotspots","laptop-class"]},{"selected":["hotspots","reminders"]},{"selected":["ebooks","laptop-class"]},{"selected":["laptop-class","reminders"]},{"selected":["computers","reminders"]}],"fact_table_binding":{"label_column":0,"columns":{"cost":1,"offline":2,"multilingual":3}},"preferences":["Reaching more residents or leaving budget for supplies may be preferable but is not graded."]}'::jsonb, 'community.library-inclusion@1-with-constraint/v1', '{"version":"rubric-2026-10-a","dimensions":["constraints","alternatives","assumptions","trade_offs"],"constraint_cues":{"TWO-PROGRAMMES":["two programmes","two programs","exactly two","both"],"BUDGET":["budget","$3,000","3000","3,000","cost","total","afford","over"],"LANGUAGE":["spanish","vietnamese","language","interpreter","translat","multilingual"],"NO-HOME-INTERNET":["home internet","without internet","no internet","offline","connection","hotspot","in the library","in-library","at the library"]},"edge_case_cues":["no smartphone","older","elderly","disab","transport","can''t get to"],"trade_off_cues":["trade-off","tradeoff","instead","would miss","leftover","left over","versus","on the other hand"],"anchors":{}}'::jsonb, 'rubric-2026-10-a', '{"text":"Pairs over $3,000 are out (hotspots with e-books or computers, laptop class with computers, e-books with computers). Of the pairs left, e-books plus reminders is the only one where neither programme works without home internet, so it fails that requirement. Five pairs qualify. The laptop class meets both the language and offline requirements by itself, which makes it a flexible anchor.","accepted_summary":"Any of five qualifying pairs; e-books + reminders fails the no-home-internet requirement."}'::jsonb, '{"author_checked":true,"independent_review":{"status":"pending","reviewer":null,"date":null},"notes":"Matched variants differ only in the no-home-internet requirement and survey fact."}'::jsonb, '{"final_answer":{"selected":["laptop-class","reminders"]},"concise_explanation":"The evening laptop class works for residents without home internet and has Spanish and Vietnamese interpreters. Adding the reminder service keeps the total at $1,300, well within the $3,000 budget.","stated_alternatives":["Hotspot lending plus the laptop class costs $2,700 and reaches more homes.","Two public computers plus reminders costs $2,600."],"stated_assumptions":["Residents can travel to the library in the evening."],"cited_constraint_ids":["TWO-PROGRAMMES","BUDGET","LANGUAGE","NO-HOME-INTERNET"],"uncertainty_notes":"The survey does not say how many residents can attend evening classes."}'::jsonb) on conflict (problem_version_id) do nothing;
