insert into problem_versions (id, family_id, slug, version, variant, category, difficulty, est_minutes, title, public_payload, provenance, content_hash) values ('community.venue@1-with-constraint', 'community.venue', 'accessible-venue', '1', 'with-constraint', 'community', 'easy', '6', 'Pick a venue for the coding showcase', '{"summary":"Choose a venue for a 60-guest youth coding showcase using the requirements and the venue table.","statement":"The fictional Maple Harbor Youth Coding Club is hosting an end-of-term showcase for 60 guests: students, families, and mentors. You are helping the organisers choose one venue from the table below. Choose a venue that meets every listed requirement. If more than one venue qualifies, any qualifying venue is accepted; say why you chose yours.","facts":["The club''s budget for the venue is $500.","Two of the confirmed guests use wheelchairs.","Most families will arrive by bus or light rail."],"fact_table":{"caption":"Venue options (fictional)","columns":["Venue","Cost","Capacity","Step-free entrance","Walk from transit"],"rows":[["Riverside Hall","$450","80","No — three front steps, no ramp","4 min"],["Oak Street Library Room","$300","50","Yes","3 min"],["Harbor Community Center","$480","70","Yes — ramp and lift","9 min"],["Summit Arts Loft","$380","90","No — second floor, no lift","2 min"],["Westfield School Gym","$520","150","Yes","6 min"],["Pine Grove Pavilion","$250","100","Yes","25 min"]]},"constraints":[{"id":"PICK-ONE","text":"Choose exactly one venue.","kind":"rule"},{"id":"BUDGET","text":"Venue cost must be $500 or less.","kind":"rule"},{"id":"CAPACITY","text":"Capacity must be at least 60 people.","kind":"rule"},{"id":"STEP-FREE","text":"The venue must have a step-free entrance so every guest can get in.","kind":"practical"},{"id":"TRANSIT","text":"The venue must be at most a 12-minute walk from transit.","kind":"rule"}],"answer_format":{"kind":"choice_fields","instructions":"Choose one venue.","fields":[{"id":"venue","label":"Venue","options":[{"id":"riverside","label":"Riverside Hall"},{"id":"oak","label":"Oak Street Library Room"},{"id":"harbor","label":"Harbor Community Center"},{"id":"summit","label":"Summit Arts Loft"},{"id":"westfield","label":"Westfield School Gym"},{"id":"pinegrove","label":"Pine Grove Pavilion"}]}]},"explanation_prompt":"Which requirements ruled venues out? What trade-offs did you weigh between the remaining options?"}'::jsonb, '{"author":"Reasoning Lab project team","created":"2026-10-16","license":"MIT","origin":"original","fictional_data":true,"contamination_note":"Original fictional data; not published before 2026-10-16."}'::jsonb, '34a8476906359120bd20a76045f0fe5b5a41d7d56a71f009c775a11a8558ac80') on conflict (id) do nothing;
insert into problem_keys (problem_version_id, validator, validator_version, rubric, rubric_version, reviewed_explanation, review, reference_output) values ('community.venue@1-with-constraint', '{"engine":"rules","attributes":{"riverside":{"cost":450,"capacity":80,"step_free":false,"transit_min":4},"oak":{"cost":300,"capacity":50,"step_free":true,"transit_min":3},"harbor":{"cost":480,"capacity":70,"step_free":true,"transit_min":9},"summit":{"cost":380,"capacity":90,"step_free":false,"transit_min":2},"westfield":{"cost":520,"capacity":150,"step_free":true,"transit_min":6},"pinegrove":{"cost":250,"capacity":100,"step_free":true,"transit_min":25}},"rules":[{"type":"all_fields_answered","constraint_id":"PICK-ONE"},{"type":"field_attr","constraint_id":"BUDGET","field":"venue","attr":"cost","op":"lte","value":500},{"type":"field_attr","constraint_id":"CAPACITY","field":"venue","attr":"capacity","op":"gte","value":60},{"type":"field_attr","constraint_id":"STEP-FREE","field":"venue","attr":"step_free","op":"eq","value":true},{"type":"field_attr","constraint_id":"TRANSIT","field":"venue","attr":"transit_min","op":"lte","value":12}],"expected_solutions":[{"fields":{"venue":"harbor"}}],"fact_table_binding":{"label_column":0,"columns":{"cost":1,"capacity":2,"step_free":3,"transit_min":4}},"preferences":["A lower cost or shorter walk may be preferable, but any venue meeting every requirement is accepted."]}'::jsonb, 'community.venue@1-with-constraint/v1', '{"version":"rubric-2026-10-a","dimensions":["constraints","alternatives","assumptions","trade_offs"],"constraint_cues":{"PICK-ONE":["one venue","chose","choose","pick"],"BUDGET":["budget","$500","cost","price","afford","cheap","expensive","over budget"],"CAPACITY":["capacity","60","fit","too small","seats","room for"],"STEP-FREE":["step-free","step free","wheelchair","ramp","lift","elevator","accessible","accessibility","steps","stairs"],"TRANSIT":["transit","bus","light rail","walk","12 min","12-minute","minutes away","too far"]},"edge_case_cues":[],"trade_off_cues":["trade-off","tradeoff","cheaper","closer","versus","instead","on the other hand"],"anchors":{"constraints":"Credit requires naming the requirement (e.g. wheelchair access), not just the venue."}}'::jsonb, 'rubric-2026-10-a', '{"text":"Westfield is over budget, Oak Street is too small, and Pine Grove is a 25-minute walk from transit. Of the rest, Riverside Hall has front steps with no ramp and Summit Arts Loft is on a second floor with no lift, so neither meets the step-free requirement. Harbor Community Center is the only venue that meets every requirement, though it is the furthest of the qualifying walks at 9 minutes.","accepted_summary":"Harbor Community Center (unique)."}'::jsonb, '{"author_checked":true,"independent_review":{"status":"pending","reviewer":null,"date":null},"notes":"Matched variants differ only in the STEP-FREE requirement and the wheelchair-user fact."}'::jsonb, '{"final_answer":{"fields":{"venue":"summit"}},"concise_explanation":"Westfield is over the $500 budget, Oak Street is too small for 60 guests, and Pine Grove is too far from transit. Summit Arts Loft is the cheapest remaining option at $380 and only a 2-minute walk from transit.","stated_alternatives":["Riverside Hall at $450.","Harbor Community Center at $480."],"stated_assumptions":["Lower cost is better for a small club."],"cited_constraint_ids":["BUDGET","CAPACITY","TRANSIT"],"uncertainty_notes":""}'::jsonb) on conflict (problem_version_id) do nothing;
insert into problem_versions (id, family_id, slug, version, variant, category, difficulty, est_minutes, title, public_payload, provenance, content_hash) values ('community.venue@1-without-constraint', 'community.venue', 'accessible-venue', '1', 'without-constraint', 'community', 'easy', '6', 'Pick a venue for the coding showcase', '{"summary":"Choose a venue for a 60-guest youth coding showcase using the requirements and the venue table.","statement":"The fictional Maple Harbor Youth Coding Club is hosting an end-of-term showcase for 60 guests: students, families, and mentors. You are helping the organisers choose one venue from the table below. Choose a venue that meets every listed requirement. If more than one venue qualifies, any qualifying venue is accepted; say why you chose yours.","facts":["The club''s budget for the venue is $500.","Most families will arrive by bus or light rail."],"fact_table":{"caption":"Venue options (fictional)","columns":["Venue","Cost","Capacity","Step-free entrance","Walk from transit"],"rows":[["Riverside Hall","$450","80","No — three front steps, no ramp","4 min"],["Oak Street Library Room","$300","50","Yes","3 min"],["Harbor Community Center","$480","70","Yes — ramp and lift","9 min"],["Summit Arts Loft","$380","90","No — second floor, no lift","2 min"],["Westfield School Gym","$520","150","Yes","6 min"],["Pine Grove Pavilion","$250","100","Yes","25 min"]]},"constraints":[{"id":"PICK-ONE","text":"Choose exactly one venue.","kind":"rule"},{"id":"BUDGET","text":"Venue cost must be $500 or less.","kind":"rule"},{"id":"CAPACITY","text":"Capacity must be at least 60 people.","kind":"rule"},{"id":"TRANSIT","text":"The venue must be at most a 12-minute walk from transit.","kind":"rule"}],"answer_format":{"kind":"choice_fields","instructions":"Choose one venue.","fields":[{"id":"venue","label":"Venue","options":[{"id":"riverside","label":"Riverside Hall"},{"id":"oak","label":"Oak Street Library Room"},{"id":"harbor","label":"Harbor Community Center"},{"id":"summit","label":"Summit Arts Loft"},{"id":"westfield","label":"Westfield School Gym"},{"id":"pinegrove","label":"Pine Grove Pavilion"}]}]},"explanation_prompt":"Which requirements ruled venues out? What trade-offs did you weigh between the remaining options?"}'::jsonb, '{"author":"Reasoning Lab project team","created":"2026-10-16","license":"MIT","origin":"original","fictional_data":true,"contamination_note":"Original fictional data; not published before 2026-10-16."}'::jsonb, '115a61e81f1b05db78353528eb552a9d62ec73a8b152dd7f3f299d83356d79f2') on conflict (id) do nothing;
insert into problem_keys (problem_version_id, validator, validator_version, rubric, rubric_version, reviewed_explanation, review, reference_output) values ('community.venue@1-without-constraint', '{"engine":"rules","attributes":{"riverside":{"cost":450,"capacity":80,"step_free":false,"transit_min":4},"oak":{"cost":300,"capacity":50,"step_free":true,"transit_min":3},"harbor":{"cost":480,"capacity":70,"step_free":true,"transit_min":9},"summit":{"cost":380,"capacity":90,"step_free":false,"transit_min":2},"westfield":{"cost":520,"capacity":150,"step_free":true,"transit_min":6},"pinegrove":{"cost":250,"capacity":100,"step_free":true,"transit_min":25}},"rules":[{"type":"all_fields_answered","constraint_id":"PICK-ONE"},{"type":"field_attr","constraint_id":"BUDGET","field":"venue","attr":"cost","op":"lte","value":500},{"type":"field_attr","constraint_id":"CAPACITY","field":"venue","attr":"capacity","op":"gte","value":60},{"type":"field_attr","constraint_id":"TRANSIT","field":"venue","attr":"transit_min","op":"lte","value":12}],"expected_solutions":[{"fields":{"venue":"riverside"}},{"fields":{"venue":"harbor"}},{"fields":{"venue":"summit"}}],"fact_table_binding":{"label_column":0,"columns":{"cost":1,"capacity":2,"step_free":3,"transit_min":4}},"preferences":["A lower cost or shorter walk may be preferable, but any venue meeting every requirement is accepted."]}'::jsonb, 'community.venue@1-without-constraint/v1', '{"version":"rubric-2026-10-a","dimensions":["constraints","alternatives","assumptions","trade_offs"],"constraint_cues":{"PICK-ONE":["one venue","chose","choose","pick"],"BUDGET":["budget","$500","cost","price","afford","cheap","expensive","over budget"],"CAPACITY":["capacity","60","fit","too small","seats","room for"],"TRANSIT":["transit","bus","light rail","walk","12 min","12-minute","minutes away","too far"]},"edge_case_cues":[],"trade_off_cues":["trade-off","tradeoff","cheaper","closer","versus","instead","on the other hand"],"anchors":{"constraints":"Credit requires naming the requirement (e.g. wheelchair access), not just the venue."}}'::jsonb, 'rubric-2026-10-a', '{"text":"Westfield is over budget, Oak Street is too small, and Pine Grove is a 25-minute walk from transit. Riverside Hall, Harbor Community Center, and Summit Arts Loft all meet the listed requirements. Summit is cheapest and closest; Harbor is the only remaining option with a step-free entrance, which was not a listed requirement in this version but may matter to guests.","accepted_summary":"Riverside Hall, Harbor Community Center, or Summit Arts Loft."}'::jsonb, '{"author_checked":true,"independent_review":{"status":"pending","reviewer":null,"date":null},"notes":"Matched variants differ only in the STEP-FREE requirement and the wheelchair-user fact."}'::jsonb, '{"final_answer":{"fields":{"venue":"summit"}},"concise_explanation":"Westfield is over the $500 budget, Oak Street is too small for 60 guests, and Pine Grove is too far from transit. Summit Arts Loft is the cheapest remaining option at $380 and only a 2-minute walk from transit.","stated_alternatives":["Riverside Hall at $450.","Harbor Community Center at $480."],"stated_assumptions":["Lower cost is better for a small club."],"cited_constraint_ids":["BUDGET","CAPACITY","TRANSIT"],"uncertainty_notes":""}'::jsonb) on conflict (problem_version_id) do nothing;
insert into problem_versions (id, family_id, slug, version, variant, category, difficulty, est_minutes, title, public_payload, provenance, content_hash) values ('community.volunteer-shifts@1-with-constraint', 'community.volunteer-shifts', 'beach-cleanup-shifts', '1', 'with-constraint', 'community', 'easy', '6', 'Beach clean-up shift leads', '{"summary":"Assign a lead volunteer to each of three clean-up shifts using availability and skills.","statement":"A fictional beach clean-up runs three shifts on Saturday. Each shift needs exactly one shift lead. Four volunteers have offered to lead. Assign one lead to each shift so that every requirement is met. If more than one assignment works, any valid assignment is accepted.","facts":["Morning shift: 8–10 a.m. Midday shift: 10 a.m.–12 p.m. Afternoon shift: 12–2 p.m.","The afternoon shift runs at low tide near the rocks, where slips are most likely."],"fact_table":{"caption":"Volunteer leads (fictional)","columns":["Volunteer","Available","First-aid certified"],"rows":[["Amara","Morning, Midday","Yes"],["Bo","Midday, Afternoon","No"],["Carmen","Morning","No"],["Dev","Morning, Afternoon","Yes"]]},"constraints":[{"id":"ONE-LEAD-EACH","text":"Each shift has exactly one lead.","kind":"rule"},{"id":"FAIR-LOAD","text":"No one leads more than one shift.","kind":"rule"},{"id":"AVAILABILITY","text":"A lead must be available for the shift they lead.","kind":"rule"},{"id":"FIRST-AID","text":"The afternoon lead must be first-aid certified.","kind":"practical"}],"answer_format":{"kind":"choice_fields","instructions":"Choose a lead for each shift.","fields":[{"id":"morning","label":"Morning lead","options":[{"id":"amara","label":"Amara"},{"id":"bo","label":"Bo"},{"id":"carmen","label":"Carmen"},{"id":"dev","label":"Dev"}]},{"id":"midday","label":"Midday lead","options":[{"id":"amara","label":"Amara"},{"id":"bo","label":"Bo"},{"id":"carmen","label":"Carmen"},{"id":"dev","label":"Dev"}]},{"id":"afternoon","label":"Afternoon lead","options":[{"id":"amara","label":"Amara"},{"id":"bo","label":"Bo"},{"id":"carmen","label":"Carmen"},{"id":"dev","label":"Dev"}]}]},"explanation_prompt":"Which shift did you fill first? Who is left without a shift, and is that fair?"}'::jsonb, '{"author":"Reasoning Lab project team","created":"2026-10-16","license":"MIT","origin":"original","fictional_data":true,"contamination_note":"Original fictional data not published before 2026-10-16."}'::jsonb, '7df96844b33a5a92e02652ff5a338a9c9ec0ce39f2fa46c2e0e32e1495827c00') on conflict (id) do nothing;
insert into problem_keys (problem_version_id, validator, validator_version, rubric, rubric_version, reviewed_explanation, review, reference_output) values ('community.volunteer-shifts@1-with-constraint', '{"engine":"rules","attributes":{"amara":{"available":"Morning, Midday","first_aid":true},"bo":{"available":"Midday, Afternoon","first_aid":false},"carmen":{"available":"Morning","first_aid":false},"dev":{"available":"Morning, Afternoon","first_aid":true}},"rules":[{"type":"all_fields_answered","constraint_id":"ONE-LEAD-EACH"},{"type":"distinct","constraint_id":"FAIR-LOAD"},{"type":"field_in","constraint_id":"AVAILABILITY","field":"morning","allowed":["amara","carmen","dev"]},{"type":"field_in","constraint_id":"AVAILABILITY","field":"midday","allowed":["amara","bo"]},{"type":"field_in","constraint_id":"AVAILABILITY","field":"afternoon","allowed":["bo","dev"]},{"type":"field_attr","constraint_id":"FIRST-AID","field":"afternoon","attr":"first_aid","op":"eq","value":true}],"expected_solutions":[{"fields":{"morning":"amara","midday":"bo","afternoon":"dev"}},{"fields":{"morning":"carmen","midday":"amara","afternoon":"dev"}},{"fields":{"morning":"carmen","midday":"bo","afternoon":"dev"}}],"fact_table_binding":{"label_column":0,"columns":{"available":1,"first_aid":2}},"preferences":["Giving a newer volunteer a lead role can be a reasonable goal but is not graded."]}'::jsonb, 'community.volunteer-shifts@1-with-constraint/v1', '{"version":"rubric-2026-10-a","dimensions":["constraints","alternatives","assumptions","trade_offs"],"constraint_cues":{"ONE-LEAD-EACH":["one lead","each shift","every shift"],"FAIR-LOAD":["more than one","two shifts","fair","once","only one shift","workload"],"AVAILABILITY":["available","availability","free","only morning","can only"],"FIRST-AID":["first aid","first-aid","certified","certification","rocks","low tide","safety"]},"edge_case_cues":["sick","cancel","backup","drops out","no-show"],"trade_off_cues":["left out","left without","fair","instead","either","could also"],"anchors":{}}'::jsonb, 'rubric-2026-10-a', '{"text":"Only Bo and Dev are available in the afternoon, and only Dev is first-aid certified, so Dev leads the afternoon. Morning can then go to Amara or Carmen and midday to Amara or Bo, as long as nobody leads twice. Three assignments work; each leaves one volunteer without a lead role.","accepted_summary":"Dev leads the afternoon; morning/midday: Amara/Bo, Carmen/Amara, or Carmen/Bo."}'::jsonb, '{"author_checked":true,"independent_review":{"status":"pending","reviewer":null,"date":null},"notes":"Matched variants differ only in the first-aid requirement."}'::jsonb, '{"final_answer":{"fields":{"morning":"carmen","midday":"amara","afternoon":"bo"}},"concise_explanation":"Carmen is only free in the morning, so she leads the morning shift. Amara takes midday. Bo is available in the afternoon, so Bo leads the afternoon, which gives Dev a break.","stated_alternatives":["Dev could lead the afternoon instead of Bo."],"stated_assumptions":["Spreading lead roles across more people is fairer."],"cited_constraint_ids":["AVAILABILITY","FAIR-LOAD"],"uncertainty_notes":""}'::jsonb) on conflict (problem_version_id) do nothing;
insert into problem_versions (id, family_id, slug, version, variant, category, difficulty, est_minutes, title, public_payload, provenance, content_hash) values ('community.volunteer-shifts@1-without-constraint', 'community.volunteer-shifts', 'beach-cleanup-shifts', '1', 'without-constraint', 'community', 'easy', '6', 'Beach clean-up shift leads', '{"summary":"Assign a lead volunteer to each of three clean-up shifts using availability and skills.","statement":"A fictional beach clean-up runs three shifts on Saturday. Each shift needs exactly one shift lead. Four volunteers have offered to lead. Assign one lead to each shift so that every requirement is met. If more than one assignment works, any valid assignment is accepted.","facts":["Morning shift: 8–10 a.m. Midday shift: 10 a.m.–12 p.m. Afternoon shift: 12–2 p.m."],"fact_table":{"caption":"Volunteer leads (fictional)","columns":["Volunteer","Available","First-aid certified"],"rows":[["Amara","Morning, Midday","Yes"],["Bo","Midday, Afternoon","No"],["Carmen","Morning","No"],["Dev","Morning, Afternoon","Yes"]]},"constraints":[{"id":"ONE-LEAD-EACH","text":"Each shift has exactly one lead.","kind":"rule"},{"id":"FAIR-LOAD","text":"No one leads more than one shift.","kind":"rule"},{"id":"AVAILABILITY","text":"A lead must be available for the shift they lead.","kind":"rule"}],"answer_format":{"kind":"choice_fields","instructions":"Choose a lead for each shift.","fields":[{"id":"morning","label":"Morning lead","options":[{"id":"amara","label":"Amara"},{"id":"bo","label":"Bo"},{"id":"carmen","label":"Carmen"},{"id":"dev","label":"Dev"}]},{"id":"midday","label":"Midday lead","options":[{"id":"amara","label":"Amara"},{"id":"bo","label":"Bo"},{"id":"carmen","label":"Carmen"},{"id":"dev","label":"Dev"}]},{"id":"afternoon","label":"Afternoon lead","options":[{"id":"amara","label":"Amara"},{"id":"bo","label":"Bo"},{"id":"carmen","label":"Carmen"},{"id":"dev","label":"Dev"}]}]},"explanation_prompt":"Which shift did you fill first? Who is left without a shift, and is that fair?"}'::jsonb, '{"author":"Reasoning Lab project team","created":"2026-10-16","license":"MIT","origin":"original","fictional_data":true,"contamination_note":"Original fictional data not published before 2026-10-16."}'::jsonb, 'be27f67ab2f14af3c560ea75e733cef9c471a9369a16d4d267798762a6ffcb06') on conflict (id) do nothing;
insert into problem_keys (problem_version_id, validator, validator_version, rubric, rubric_version, reviewed_explanation, review, reference_output) values ('community.volunteer-shifts@1-without-constraint', '{"engine":"rules","attributes":{"amara":{"available":"Morning, Midday","first_aid":true},"bo":{"available":"Midday, Afternoon","first_aid":false},"carmen":{"available":"Morning","first_aid":false},"dev":{"available":"Morning, Afternoon","first_aid":true}},"rules":[{"type":"all_fields_answered","constraint_id":"ONE-LEAD-EACH"},{"type":"distinct","constraint_id":"FAIR-LOAD"},{"type":"field_in","constraint_id":"AVAILABILITY","field":"morning","allowed":["amara","carmen","dev"]},{"type":"field_in","constraint_id":"AVAILABILITY","field":"midday","allowed":["amara","bo"]},{"type":"field_in","constraint_id":"AVAILABILITY","field":"afternoon","allowed":["bo","dev"]}],"expected_solutions":[{"fields":{"morning":"amara","midday":"bo","afternoon":"dev"}},{"fields":{"morning":"carmen","midday":"amara","afternoon":"bo"}},{"fields":{"morning":"carmen","midday":"amara","afternoon":"dev"}},{"fields":{"morning":"carmen","midday":"bo","afternoon":"dev"}},{"fields":{"morning":"dev","midday":"amara","afternoon":"bo"}}],"fact_table_binding":{"label_column":0,"columns":{"available":1,"first_aid":2}},"preferences":["Giving a newer volunteer a lead role can be a reasonable goal but is not graded."]}'::jsonb, 'community.volunteer-shifts@1-without-constraint/v1', '{"version":"rubric-2026-10-a","dimensions":["constraints","alternatives","assumptions","trade_offs"],"constraint_cues":{"ONE-LEAD-EACH":["one lead","each shift","every shift"],"FAIR-LOAD":["more than one","two shifts","fair","once","only one shift","workload"],"AVAILABILITY":["available","availability","free","only morning","can only"]},"edge_case_cues":["sick","cancel","backup","drops out","no-show"],"trade_off_cues":["left out","left without","fair","instead","either","could also"],"anchors":{}}'::jsonb, 'rubric-2026-10-a', '{"text":"The afternoon can go to Bo or Dev. If Bo leads the afternoon, midday must be Amara and morning Carmen or Dev. If Dev leads the afternoon, morning is Amara or Carmen and midday Amara or Bo without repeats. Five assignments meet every listed requirement.","accepted_summary":"Any of five assignments that respect availability and one-shift-each."}'::jsonb, '{"author_checked":true,"independent_review":{"status":"pending","reviewer":null,"date":null},"notes":"Matched variants differ only in the first-aid requirement."}'::jsonb, '{"final_answer":{"fields":{"morning":"carmen","midday":"amara","afternoon":"bo"}},"concise_explanation":"Carmen is only free in the morning, so she leads the morning shift. Amara takes midday. Bo is available in the afternoon, so Bo leads the afternoon, which gives Dev a break.","stated_alternatives":["Dev could lead the afternoon instead of Bo."],"stated_assumptions":["Spreading lead roles across more people is fairer."],"cited_constraint_ids":["AVAILABILITY","FAIR-LOAD"],"uncertainty_notes":""}'::jsonb) on conflict (problem_version_id) do nothing;
insert into problem_versions (id, family_id, slug, version, variant, category, difficulty, est_minutes, title, public_payload, provenance, content_hash) values ('debugging.average-empty@1', 'debugging.average-empty', 'average-empty-list', '1', 'standard', 'debugging', 'easy', '4', 'Average of an empty list', '{"summary":"A quiz-score average shows “NaN” for new students. Find the faulty line and pick a fix.","statement":"A class dashboard shows each student''s average quiz score. For students who have not taken any quizzes yet, the dashboard displays “NaN”. The specification says average() must return null when the list is empty, and the ordinary average otherwise. Identify the line that produces the wrong result for an empty list, then choose a change that makes the function meet the specification.","facts":["scores is always an array of numbers (it may be empty).","In JavaScript, 0 / 0 evaluates to NaN; it does not throw an error."],"code":{"language":"javascript","lines":["function average(scores) {","  let total = 0;","  for (const s of scores) {","    total += s;","  }","  return total / scores.length;","}"]},"constraints":[{"id":"EMPTY-RETURNS-NULL","text":"An empty list must return null.","kind":"rule"},{"id":"NORMAL-AVERAGE","text":"A non-empty list must still return the ordinary average (for example [4, 8] → 6).","kind":"rule"}],"answer_format":{"kind":"choice_fields","instructions":"Choose the faulty line and the fix.","fields":[{"id":"line","label":"Which line produces the wrong result for an empty list?","options":[{"id":"l2","label":"Line 2"},{"id":"l3","label":"Line 3"},{"id":"l4","label":"Line 4"},{"id":"l6","label":"Line 6"}]},{"id":"fix","label":"Which change meets the specification?","options":[{"id":"a","label":"Add a guard before line 2","code":"  if (scores.length === 0) return null;","patch":{"op":"insert_before","line":2}},{"id":"b","label":"Change line 6","code":"  return total / (scores.length + 1);","patch":{"op":"replace","line":6}},{"id":"c","label":"Change line 6","code":"  return scores.length > 0 ? total / scores.length : null;","patch":{"op":"replace","line":6}},{"id":"d","label":"Change line 2","code":"  let total = 1;","patch":{"op":"replace","line":2}}]}]},"explanation_prompt":"Why does the empty case fail? How do you know your fix keeps normal averages correct?"}'::jsonb, '{"author":"Reasoning Lab project team","created":"2026-10-16","license":"MIT","origin":"original","fictional_data":true,"contamination_note":"Empty-list division is a very common teaching bug; models have almost certainly seen close variants."}'::jsonb, 'c068c3b3c7613dcb0728384cea1794447f99a0958c3144ef1ce944aced2b81fa') on conflict (id) do nothing;
insert into problem_keys (problem_version_id, validator, validator_version, rubric, rubric_version, reviewed_explanation, review, reference_output) values ('debugging.average-empty@1', '{"engine":"answer_key","accepted":[{"line":"l6","fix":"a"},{"line":"l6","fix":"c"}],"harness":{"entry":"average","helpers":[],"cases":[{"name":"empty list returns null","check":"average([]) === null"},{"name":"two values","check":"average([4, 8]) === 6"},{"name":"one value","check":"average([5]) === 5"},{"name":"negatives","check":"average([-2, 2]) === 0"},{"name":"fractional","check":"average([1, 2]) === 1.5"}],"patch_field":"fix"}}'::jsonb, 'debugging.average-empty@1/v1', '{"version":"rubric-2026-10-a","dimensions":["constraints","edge_cases","alternatives","assumptions"],"constraint_cues":{"EMPTY-RETURNS-NULL":["return null","returns null","null","empty"],"NORMAL-AVERAGE":["still","normal","non-empty","other cases","[4, 8]","regular average","ordinary average"]},"edge_case_cues":["empty","no quizzes","length is 0","length === 0","zero","0 / 0","nan"],"trade_off_cues":[],"anchors":{"edge_cases":"Credit for naming the empty-list case explicitly."}}'::jsonb, 'rubric-2026-10-a', '{"text":"With an empty list, total stays 0 and scores.length is 0, so line 6 computes 0 / 0, which is NaN in JavaScript rather than an error. Either add an early return of null when the list is empty (option a) or make line 6 return null when the length is 0 (option c). Both keep ordinary averages unchanged. Option b changes every average, and option d adds 1 to every total.","accepted_summary":"Line 6 with fix a or fix c."}'::jsonb, '{"author_checked":true,"independent_review":{"status":"pending","reviewer":null,"date":null},"notes":"Patch outcomes confirmed by running each patched function against the reviewed cases in tests (author code only; participant code is never executed)."}'::jsonb, '{"final_answer":{"fields":{"line":"l6","fix":"c"}},"concise_explanation":"For an empty list, line 6 divides 0 by 0, which is NaN in JavaScript. Returning null when the length is 0 and the normal average otherwise fixes it without changing other results.","stated_alternatives":["An early return of null at the top of the function would also work."],"stated_assumptions":["scores only contains numbers."],"cited_constraint_ids":["EMPTY-RETURNS-NULL","NORMAL-AVERAGE"],"uncertainty_notes":""}'::jsonb) on conflict (problem_version_id) do nothing;
insert into problem_versions (id, family_id, slug, version, variant, category, difficulty, est_minutes, title, public_payload, provenance, content_hash) values ('debugging.earliest-shift@1', 'debugging.earliest-shift', 'earliest-shift', '1', 'standard', 'debugging', 'moderate', '7', 'The 1 p.m. shift that came first', '{"summary":"A function that finds the earliest shift sometimes picks an afternoon shift. Find the cause and choose a fix.","statement":"A food-bank rota stores shift start times as text on a 24-hour clock, such as \"9:30\" or \"13:00\". earliestShift() should return the shift with the earliest start time. With shifts starting at \"9:30\" and \"13:00\", it returns the 13:00 shift. Identify the faulty line and choose a change that makes the function correct for any valid times.","facts":["Times look like \"H:MM\" or \"HH:MM\"; hours may have one or two digits.","shifts always contains at least one shift.","The helper toMinutes(\"13:05\") returns 785 (13 × 60 + 5)."],"code":{"language":"javascript","lines":["const toMinutes = (t) => { const [h, m] = t.split(\":\").map(Number); return h * 60 + m; };","","function earliestShift(shifts) {","  let earliest = shifts[0];","  for (const shift of shifts) {","    if (shift.start < earliest.start) {","      earliest = shift;","    }","  }","  return earliest;","}"]},"constraints":[{"id":"TRUE-EARLIEST","text":"Return the shift whose start time is earliest in the day.","kind":"rule"},{"id":"MIXED-DIGITS","text":"Must work when one-digit and two-digit hours are mixed (e.g. \"9:30\" and \"13:00\").","kind":"rule"}],"answer_format":{"kind":"choice_fields","instructions":"Choose the faulty line and the fix.","fields":[{"id":"line","label":"Which line makes the wrong choice?","options":[{"id":"l4","label":"Line 4"},{"id":"l5","label":"Line 5"},{"id":"l6","label":"Line 6"},{"id":"l10","label":"Line 10"}]},{"id":"fix","label":"Which change makes the function correct?","options":[{"id":"a","label":"Change line 6","code":"    if (toMinutes(shift.start) < toMinutes(earliest.start)) {","patch":{"op":"replace","line":6}},{"id":"b","label":"Change line 6","code":"    if (shift.start.length < earliest.start.length) {","patch":{"op":"replace","line":6}},{"id":"c","label":"Change line 6","code":"    if (shift.start.padStart(5, \"0\") < earliest.start.padStart(5, \"0\")) {","patch":{"op":"replace","line":6}},{"id":"d","label":"Change line 6","code":"    if (Number(shift.start) < Number(earliest.start)) {","patch":{"op":"replace","line":6}}]}]},"explanation_prompt":"Why does \"13:00\" look earlier than \"9:30\" to the original code? What inputs did you use to check your fix?"}'::jsonb, '{"author":"Reasoning Lab project team","created":"2026-10-16","license":"MIT","origin":"original","fictional_data":true,"contamination_note":"String comparison of times is a known bug pattern; option c is a less obvious but valid alternative."}'::jsonb, '799554c946595b4d976f8b5e5607bd1d4288ff85976d529a57b59d2ad1fb694c') on conflict (id) do nothing;
insert into problem_keys (problem_version_id, validator, validator_version, rubric, rubric_version, reviewed_explanation, review, reference_output) values ('debugging.earliest-shift@1', '{"engine":"answer_key","accepted":[{"line":"l6","fix":"a"},{"line":"l6","fix":"c"}],"harness":{"entry":"earliestShift","helpers":[],"cases":[{"name":"mixed digits","check":"earliestShift([{ start: \"9:30\" }, { start: \"13:00\" }, { start: \"8:15\" }]).start === \"8:15\""},{"name":"afternoon first in list","check":"earliestShift([{ start: \"13:00\" }, { start: \"9:30\" }]).start === \"9:30\""},{"name":"same digit count","check":"earliestShift([{ start: \"10:00\" }, { start: \"09:45\" }]).start === \"09:45\""},{"name":"single-digit vs noon","check":"earliestShift([{ start: \"12:00\" }, { start: \"7:05\" }]).start === \"7:05\""},{"name":"single shift","check":"earliestShift([{ start: \"14:20\" }]).start === \"14:20\""}],"patch_field":"fix"}}'::jsonb, 'debugging.earliest-shift@1/v1', '{"version":"rubric-2026-10-a","dimensions":["constraints","edge_cases","alternatives","assumptions"],"constraint_cues":{"TRUE-EARLIEST":["minutes","tominutes","numeric","as numbers","convert"],"MIXED-DIGITS":["character","alphabetical","lexicographic","string comparison","compares strings","text comparison","\"1\" < \"9\"","one digit","two digit","pad","leading zero"]},"edge_case_cues":["leading zero","09","same time","tie","midnight","0:00","single shift"],"trade_off_cues":[],"anchors":{}}'::jsonb, 'rubric-2026-10-a', '{"text":"Line 6 compares the times as text, character by character, so \"13:00\" < \"9:30\" is true because \"1\" comes before \"9\". Converting both to minutes (option a) fixes it. Padding both to five characters with leading zeros (option c) also works, because \"09:30\" and \"13:00\" then compare correctly as text. Comparing lengths (option b) ignores the actual time, and Number(\"9:30\") is NaN (option d), so every comparison is false.","accepted_summary":"Line 6 with fix a or fix c."}'::jsonb, '{"author_checked":true,"independent_review":{"status":"pending","reviewer":null,"date":null},"notes":"Patch outcomes confirmed by running reviewed cases."}'::jsonb, '{"final_answer":{"fields":{"line":"l6","fix":"c"}},"concise_explanation":"Line 6 compares times as strings, so \"13:00\" is treated as earlier than \"9:30\" because \"1\" sorts before \"9\". Padding both times to five characters with a leading zero makes string comparison match clock order.","stated_alternatives":["Converting both times with toMinutes also works."],"stated_assumptions":["All times are valid 24-hour times."],"cited_constraint_ids":["TRUE-EARLIEST","MIXED-DIGITS"],"uncertainty_notes":""}'::jsonb) on conflict (problem_version_id) do nothing;
insert into problem_versions (id, family_id, slug, version, variant, category, difficulty, est_minutes, title, public_payload, provenance, content_hash) values ('debugging.schedule-copy@1', 'debugging.schedule-copy', 'schedule-copy', '1', 'standard', 'debugging', 'moderate', '6', 'The schedule that changed itself', '{"summary":"Adding a backup shift also changes the original schedule. Find out why and pick a fix.","statement":"A volunteer coordinator keeps the published schedule and a draft side by side so she can compare them. addBackupShift() should return a NEW array containing all the original shifts plus the backup shift at the end. The original schedule array must not change. After calling it, the coordinator sees the backup shift in the published schedule too. Identify the faulty line and choose a change that meets the specification.","facts":["schedule is an array of shift objects; shift is one more shift object.","Arrays in JavaScript are objects; assigning one to a new variable does not copy it."],"code":{"language":"javascript","lines":["function addBackupShift(schedule, shift) {","  const updated = schedule;","  updated.push(shift);","  return updated;","}"]},"constraints":[{"id":"ORIGINAL-UNCHANGED","text":"The original schedule array must not be modified.","kind":"rule"},{"id":"RESULT-HAS-SHIFT","text":"The returned array contains every original shift followed by the backup shift.","kind":"rule"}],"answer_format":{"kind":"choice_fields","instructions":"Choose the faulty line and the fix.","fields":[{"id":"line","label":"Which line is the root cause?","options":[{"id":"l2","label":"Line 2"},{"id":"l3","label":"Line 3"},{"id":"l4","label":"Line 4"}]},{"id":"fix","label":"Which change meets the specification?","options":[{"id":"a","label":"Change line 2","code":"  const updated = [...schedule];","patch":{"op":"replace","line":2}},{"id":"b","label":"Change line 2","code":"  const updated = schedule.slice();","patch":{"op":"replace","line":2}},{"id":"c","label":"Change line 2","code":"  const updated = Object.freeze(schedule);","patch":{"op":"replace","line":2}},{"id":"d","label":"Change line 4","code":"  return [...updated];","patch":{"op":"replace","line":4}}]}]},"explanation_prompt":"Why does the original change? How would you confirm the fix leaves it untouched?"}'::jsonb, '{"author":"Reasoning Lab project team","created":"2026-10-16","license":"MIT","origin":"original","fictional_data":true,"contamination_note":"Aliasing bugs are widely discussed; option d is a deliberately plausible distractor."}'::jsonb, '12e2e2e6ec1c21e339ff545f8a56a1b04e0f34f4a23b38897d97c94ee330b18e') on conflict (id) do nothing;
insert into problem_keys (problem_version_id, validator, validator_version, rubric, rubric_version, reviewed_explanation, review, reference_output) values ('debugging.schedule-copy@1', '{"engine":"answer_key","accepted":[{"line":"l2","fix":"a"},{"line":"l2","fix":"b"}],"harness":{"entry":"addBackupShift","helpers":[],"cases":[{"name":"original unchanged","check":"(() => { const s = [{ id: 1 }, { id: 2 }]; addBackupShift(s, { id: 3 }); return s.length === 2; })()"},{"name":"result appended","check":"(() => { const s = [{ id: 1 }]; const r = addBackupShift(s, { id: 9 }); return r.length === 2 && r[0].id === 1 && r[1].id === 9; })()"},{"name":"new array returned","check":"(() => { const s = []; const r = addBackupShift(s, { id: 1 }); return r !== s && s.length === 0; })()"}],"patch_field":"fix"}}'::jsonb, 'debugging.schedule-copy@1/v1', '{"version":"rubric-2026-10-a","dimensions":["constraints","edge_cases","alternatives","assumptions"],"constraint_cues":{"ORIGINAL-UNCHANGED":["original","same array","reference","mutat","alias","not a copy","doesn''t copy","does not copy"],"RESULT-HAS-SHIFT":["new array","copy","spread","slice","appended","at the end"]},"edge_case_cues":["empty schedule","empty array","shallow","nested","objects inside"],"trade_off_cues":[],"anchors":{}}'::jsonb, 'rubric-2026-10-a', '{"text":"Line 2 makes updated point to the same array as schedule, so push on line 3 changes the original. Copying first — [...schedule] (option a) or schedule.slice() (option b) — fixes it. Freezing (option c) makes push throw a TypeError. Copying on return (option d) is too late: the original was already modified on line 3. Note that both copies are shallow; the shift objects themselves are shared, which is fine here because they are not changed.","accepted_summary":"Line 2 with fix a or fix b."}'::jsonb, '{"author_checked":true,"independent_review":{"status":"pending","reviewer":null,"date":null},"notes":"Patch outcomes confirmed by running reviewed cases."}'::jsonb, '{"final_answer":{"fields":{"line":"l4","fix":"d"}},"concise_explanation":"The function returns the same array it received. Returning a copy with the spread operator gives the caller a new array that includes the backup shift.","stated_alternatives":[],"stated_assumptions":["The caller only needs a new array back."],"cited_constraint_ids":["RESULT-HAS-SHIFT"],"uncertainty_notes":""}'::jsonb) on conflict (problem_version_id) do nothing;
insert into problem_versions (id, family_id, slug, version, variant, category, difficulty, est_minutes, title, public_payload, provenance, content_hash) values ('debugging.volunteer-hours@1', 'debugging.volunteer-hours', 'volunteer-hours', '1', 'standard', 'debugging', 'easy', '4', 'Missing volunteer hours', '{"summary":"A volunteer-hours total is always a little too low. Find the faulty line and choose a fix.","statement":"A tutoring club logs volunteer shifts. Each shift is an object such as { hours: 2 }. Members report that their total hours are always too low by exactly one shift. totalHours() must return the sum of hours across all shifts (0 for an empty list). Identify the faulty line and choose a change that makes the function correct.","facts":["shifts is always an array (it may be empty).","Each shift has a numeric hours property."],"code":{"language":"javascript","lines":["function totalHours(shifts) {","  let total = 0;","  for (let i = 1; i < shifts.length; i++) {","    total += shifts[i].hours;","  }","  return total;","}"]},"constraints":[{"id":"SUM-ALL","text":"Every shift''s hours must be included in the total.","kind":"rule"},{"id":"EMPTY-ZERO","text":"An empty list must return 0 without an error.","kind":"rule"}],"answer_format":{"kind":"choice_fields","instructions":"Choose the faulty line and the fix.","fields":[{"id":"line","label":"Which line causes the missing hours?","options":[{"id":"l2","label":"Line 2"},{"id":"l3","label":"Line 3"},{"id":"l4","label":"Line 4"},{"id":"l6","label":"Line 6"}]},{"id":"fix","label":"Which change makes the function correct?","options":[{"id":"a","label":"Change line 3","code":"  for (let i = 0; i < shifts.length; i++) {","patch":{"op":"replace","line":3}},{"id":"b","label":"Change line 3","code":"  for (let i = 1; i <= shifts.length; i++) {","patch":{"op":"replace","line":3}},{"id":"c","label":"Change line 3","code":"  for (let i = 0; i <= shifts.length; i++) {","patch":{"op":"replace","line":3}},{"id":"d","label":"Replace lines 3–5","code":"  for (const shift of shifts) total += shift.hours;","patch":{"op":"replace_range","line":3,"to_line":5}}]}]},"explanation_prompt":"Which shift is being skipped, and how did you check your fix does not read past the end of the list?"}'::jsonb, '{"author":"Reasoning Lab project team","created":"2026-10-16","license":"MIT","origin":"original","fictional_data":true,"contamination_note":"Off-by-one loops are a classic teaching bug."}'::jsonb, '972f02d461dc152710a8cdd485b8f76c026fe37bbecaaf2da845bc0e418d9f93') on conflict (id) do nothing;
insert into problem_keys (problem_version_id, validator, validator_version, rubric, rubric_version, reviewed_explanation, review, reference_output) values ('debugging.volunteer-hours@1', '{"engine":"answer_key","accepted":[{"line":"l3","fix":"a"},{"line":"l3","fix":"d"}],"harness":{"entry":"totalHours","helpers":[],"cases":[{"name":"empty list","check":"totalHours([]) === 0"},{"name":"single shift","check":"totalHours([{ hours: 2 }]) === 2"},{"name":"several shifts","check":"totalHours([{ hours: 2 }, { hours: 3 }, { hours: 1.5 }]) === 6.5"}],"patch_field":"fix"}}'::jsonb, 'debugging.volunteer-hours@1/v1', '{"version":"rubric-2026-10-a","dimensions":["constraints","edge_cases","alternatives","assumptions"],"constraint_cues":{"SUM-ALL":["first shift","index 0","i = 0","skips","skipped","every shift","all shifts"],"EMPTY-ZERO":["empty","returns 0","return 0","no shifts"]},"edge_case_cues":["empty","<=","past the end","undefined","out of bounds","last index","off-by-one","off by one"],"trade_off_cues":[],"anchors":{}}'::jsonb, 'rubric-2026-10-a', '{"text":"The loop on line 3 starts at index 1, so the first shift (index 0) is never added. Starting at 0 (option a) or looping over every shift with for…of (option d) fixes it. Options b and c use <=, which reads one element past the end; shifts[shifts.length] is undefined, so .hours throws a TypeError.","accepted_summary":"Line 3 with fix a or fix d."}'::jsonb, '{"author_checked":true,"independent_review":{"status":"pending","reviewer":null,"date":null},"notes":"Patch outcomes confirmed by running reviewed cases."}'::jsonb, '{"final_answer":{"fields":{"line":"l3","fix":"a"}},"concise_explanation":"The loop starts at index 1, so the first shift is skipped. Starting at 0 includes every shift and still returns 0 for an empty list.","stated_alternatives":[],"stated_assumptions":[],"cited_constraint_ids":["SUM-ALL","EMPTY-ZERO"],"uncertainty_notes":""}'::jsonb) on conflict (problem_version_id) do nothing;
insert into problem_versions (id, family_id, slug, version, variant, category, difficulty, est_minutes, title, public_payload, provenance, content_hash) values ('logic.errand-route@1', 'logic.errand-route', 'errand-route', '1', 'standard', 'logic', 'moderate', '8', 'Volunteer errand route', '{"summary":"One volunteer, five Saturday errands, and opening-hour rules. Put the stops in a workable order.","statement":"Jo volunteers for a neighbourhood mutual-aid group. On Saturday Jo has five errands: collect a prescription from the pharmacy, return books to the library, pick up donated bread from the bakery, deliver that bread to the senior centre, and drop leftover groceries at the food bank. Put the five stops in order (stop 1 is first). Any order that follows every rule is accepted.","facts":["The pharmacy counter closes early on Saturdays.","The library book drop locks at the end of the morning.","The senior centre and the food bank share a loading zone on the same block."],"constraints":[{"id":"ONE-STOP-EACH","text":"Each errand is done exactly once.","kind":"rule"},{"id":"BREAD-STRAIGHT-TO-CENTRE","text":"The bakery pickup must be immediately followed by the senior-centre delivery.","kind":"rule"},{"id":"PHARMACY-EARLY","text":"The pharmacy must be stop 1 or stop 2.","kind":"rule"},{"id":"LIBRARY-NOT-LAST","text":"The library cannot be the last stop.","kind":"rule"},{"id":"CENTRE-THEN-FOODBANK","text":"The food bank must be the stop immediately after the senior centre.","kind":"rule"}],"answer_format":{"kind":"choice_fields","instructions":"Choose the errand for each stop.","fields":[{"id":"s1","label":"Stop 1","options":[{"id":"pharmacy","label":"Pharmacy"},{"id":"library","label":"Library"},{"id":"bakery","label":"Bakery"},{"id":"senior","label":"Senior centre"},{"id":"foodbank","label":"Food bank"}]},{"id":"s2","label":"Stop 2","options":[{"id":"pharmacy","label":"Pharmacy"},{"id":"library","label":"Library"},{"id":"bakery","label":"Bakery"},{"id":"senior","label":"Senior centre"},{"id":"foodbank","label":"Food bank"}]},{"id":"s3","label":"Stop 3","options":[{"id":"pharmacy","label":"Pharmacy"},{"id":"library","label":"Library"},{"id":"bakery","label":"Bakery"},{"id":"senior","label":"Senior centre"},{"id":"foodbank","label":"Food bank"}]},{"id":"s4","label":"Stop 4","options":[{"id":"pharmacy","label":"Pharmacy"},{"id":"library","label":"Library"},{"id":"bakery","label":"Bakery"},{"id":"senior","label":"Senior centre"},{"id":"foodbank","label":"Food bank"}]},{"id":"s5","label":"Stop 5","options":[{"id":"pharmacy","label":"Pharmacy"},{"id":"library","label":"Library"},{"id":"bakery","label":"Bakery"},{"id":"senior","label":"Senior centre"},{"id":"foodbank","label":"Food bank"}]}]},"explanation_prompt":"Which errands had to stay together? How did you place the others?"}'::jsonb, '{"author":"Reasoning Lab project team","created":"2026-10-16","license":"MIT","origin":"original","fictional_data":true,"contamination_note":"Original task; sequencing puzzles of this shape are common."}'::jsonb, '5d2bdcfcdcc1879165fa462de6f7892fbd8cd8b89116611fa91ad4c4ce6360c8') on conflict (id) do nothing;
insert into problem_keys (problem_version_id, validator, validator_version, rubric, rubric_version, reviewed_explanation, review, reference_output) values ('logic.errand-route@1', '{"engine":"rules","attributes":{},"rules":[{"type":"all_fields_answered","constraint_id":"ONE-STOP-EACH"},{"type":"distinct","constraint_id":"ONE-STOP-EACH"},{"type":"immediately_before","constraint_id":"BREAD-STRAIGHT-TO-CENTRE","a":"bakery","b":"senior","slots":["s1","s2","s3","s4","s5"]},{"type":"value_in_fields","constraint_id":"PHARMACY-EARLY","value":"pharmacy","fields":["s1","s2"]},{"type":"value_not_in_fields","constraint_id":"LIBRARY-NOT-LAST","value":"library","fields":["s5"]},{"type":"immediately_before","constraint_id":"CENTRE-THEN-FOODBANK","a":"senior","b":"foodbank","slots":["s1","s2","s3","s4","s5"]}],"expected_solutions":[{"fields":{"s1":"pharmacy","s2":"library","s3":"bakery","s4":"senior","s5":"foodbank"}},{"fields":{"s1":"library","s2":"pharmacy","s3":"bakery","s4":"senior","s5":"foodbank"}}],"preferences":[]}'::jsonb, 'logic.errand-route@1/v1', '{"version":"rubric-2026-10-a","dimensions":["constraints","alternatives","assumptions"],"constraint_cues":{"ONE-STOP-EACH":["each errand","exactly once","once each"],"BREAD-STRAIGHT-TO-CENTRE":["bakery then","bakery, senior","straight to","bread","right after the bakery","bakery immediately"],"PHARMACY-EARLY":["pharmacy","stop 1 or 2","first or second","early"],"LIBRARY-NOT-LAST":["library can''t be last","library cannot be last","library not last","library isn''t last","not last"],"CENTRE-THEN-FOODBANK":["food bank after","then the food bank","senior centre, food bank","senior center, food bank","food bank right after","loading zone","block of three","three in a row"]},"edge_case_cues":[],"trade_off_cues":[],"anchors":{}}'::jsonb, 'rubric-2026-10-a', '{"text":"Bakery, senior centre, and food bank must be three stops in a row. If that block took stops 1–3, the pharmacy would be stop 4 or 5, which breaks the early rule. If it took stops 2–4, the pharmacy would need stop 1 and the library would be last, which is not allowed. So the block is stops 3–5, and the pharmacy and library take stops 1 and 2 in either order.","accepted_summary":"Pharmacy/Library in stops 1–2 (either order), then Bakery, Senior centre, Food bank."}'::jsonb, '{"author_checked":true,"independent_review":{"status":"pending","reviewer":null,"date":null},"notes":"Two solutions; confirmed by enumeration."}'::jsonb, '{"final_answer":{"fields":{"s1":"pharmacy","s2":"library","s3":"bakery","s4":"senior","s5":"foodbank"}},"concise_explanation":"Bakery, senior center and food bank must be three stops in a row. The pharmacy must be stop 1 or 2 and the library cannot be last, so the block of three takes stops 3 to 5. Pharmacy first, then library.","stated_alternatives":["Library first and pharmacy second also works."],"stated_assumptions":["Travel time between stops is short."],"cited_constraint_ids":["BREAD-STRAIGHT-TO-CENTER","CENTER-THEN-FOODBANK","PHARMACY-EARLY","LIBRARY-NOT-LAST"],"uncertainty_notes":""}'::jsonb) on conflict (problem_version_id) do nothing;
insert into problem_versions (id, family_id, slug, version, variant, category, difficulty, est_minutes, title, public_payload, provenance, content_hash) values ('logic.garden-plots@1', 'logic.garden-plots', 'garden-plots', '1', 'standard', 'logic', 'moderate', '8', 'Community garden plots', '{"summary":"Five plots in a row, four crops, and one plot left to rest. Place everything so every rule holds.","statement":"A school community garden has five plots in a single row, numbered 1 to 5 from the gate. This season the team will plant tomatoes, beans, squash, and herbs — one crop per plot — and leave exactly one plot empty so its soil can rest. Decide what goes in each plot. Any arrangement that follows every rule is accepted.","facts":["Plots 1 and 5 are the two end plots; squash vines can spill over the edge there.","Herbs are watered by hand from a can the volunteers rest on the neighbouring empty plot."],"constraints":[{"id":"ONE-PER-PLOT","text":"Each plot holds exactly one crop or is the single empty plot; each crop is planted once.","kind":"rule"},{"id":"SQUASH-END","text":"Squash must be in an end plot (plot 1 or plot 5).","kind":"rule"},{"id":"BEANS-TOMATO-APART","text":"Beans and tomatoes must not be in neighbouring plots.","kind":"rule"},{"id":"HERBS-THEN-EMPTY","text":"The empty plot must be immediately after the herbs plot (herbs in plot n, empty in plot n+1).","kind":"rule"},{"id":"TOMATO-BEFORE-HERBS","text":"Tomatoes must be in a lower-numbered plot than herbs.","kind":"rule"}],"answer_format":{"kind":"choice_fields","instructions":"Choose what goes in each plot.","fields":[{"id":"p1","label":"Plot 1","options":[{"id":"tomatoes","label":"Tomatoes"},{"id":"beans","label":"Beans"},{"id":"squash","label":"Squash"},{"id":"herbs","label":"Herbs"},{"id":"empty","label":"Empty (resting)"}]},{"id":"p2","label":"Plot 2","options":[{"id":"tomatoes","label":"Tomatoes"},{"id":"beans","label":"Beans"},{"id":"squash","label":"Squash"},{"id":"herbs","label":"Herbs"},{"id":"empty","label":"Empty (resting)"}]},{"id":"p3","label":"Plot 3","options":[{"id":"tomatoes","label":"Tomatoes"},{"id":"beans","label":"Beans"},{"id":"squash","label":"Squash"},{"id":"herbs","label":"Herbs"},{"id":"empty","label":"Empty (resting)"}]},{"id":"p4","label":"Plot 4","options":[{"id":"tomatoes","label":"Tomatoes"},{"id":"beans","label":"Beans"},{"id":"squash","label":"Squash"},{"id":"herbs","label":"Herbs"},{"id":"empty","label":"Empty (resting)"}]},{"id":"p5","label":"Plot 5","options":[{"id":"tomatoes","label":"Tomatoes"},{"id":"beans","label":"Beans"},{"id":"squash","label":"Squash"},{"id":"herbs","label":"Herbs"},{"id":"empty","label":"Empty (resting)"}]}]},"explanation_prompt":"Which rule did you place first, and how did the others follow? Did you check other arrangements?"}'::jsonb, '{"author":"Reasoning Lab project team","created":"2026-10-16","license":"MIT","origin":"original","fictional_data":true,"contamination_note":"Original task; row-placement puzzles are a common genre."}'::jsonb, '381c11e02cbaf40899191e3d9aca1a7e143af9eef10f8dcc4ef8a2f6d6dd2f3a') on conflict (id) do nothing;
insert into problem_keys (problem_version_id, validator, validator_version, rubric, rubric_version, reviewed_explanation, review, reference_output) values ('logic.garden-plots@1', '{"engine":"rules","attributes":{},"rules":[{"type":"all_fields_answered","constraint_id":"ONE-PER-PLOT"},{"type":"distinct","constraint_id":"ONE-PER-PLOT"},{"type":"value_in_fields","constraint_id":"SQUASH-END","value":"squash","fields":["p1","p5"]},{"type":"not_adjacent","constraint_id":"BEANS-TOMATO-APART","a":"beans","b":"tomatoes","slots":["p1","p2","p3","p4","p5"]},{"type":"immediately_before","constraint_id":"HERBS-THEN-EMPTY","a":"herbs","b":"empty","slots":["p1","p2","p3","p4","p5"]},{"type":"before","constraint_id":"TOMATO-BEFORE-HERBS","a":"tomatoes","b":"herbs","slots":["p1","p2","p3","p4","p5"]}],"expected_solutions":[{"fields":{"p1":"tomatoes","p2":"herbs","p3":"empty","p4":"beans","p5":"squash"}},{"fields":{"p1":"squash","p2":"tomatoes","p3":"herbs","p4":"empty","p5":"beans"}}],"preferences":[]}'::jsonb, 'logic.garden-plots@1/v1', '{"version":"rubric-2026-10-a","dimensions":["constraints","alternatives","assumptions"],"constraint_cues":{"ONE-PER-PLOT":["one crop","one plot","exactly one","each plot"],"SQUASH-END":["squash","end plot","plot 1 or","or plot 5","an end"],"BEANS-TOMATO-APART":["beans and tomatoes","next to","neighbour","neighbor","adjacent","beans can''t","beans cannot"],"HERBS-THEN-EMPTY":["herbs then","after the herbs","after herbs","right after","empty after","immediately after","herbs, empty","herbs and then"],"TOMATO-BEFORE-HERBS":["tomatoes before","tomatoes lower","before herbs","before the herbs","lower-numbered"]},"edge_case_cues":[],"trade_off_cues":[],"anchors":{}}'::jsonb, 'rubric-2026-10-a', '{"text":"Herbs and the empty plot form a pair (herbs, empty), and tomatoes must be somewhere before herbs. Squash takes an end. If squash is in plot 5, the pair and tomatoes fit in plots 1–4 with beans left over; beans cannot sit next to tomatoes, which forces tomatoes 1, herbs 2, empty 3, beans 4. If squash is in plot 1, tomatoes go in 2, herbs 3, empty 4, and beans 5 (not next to tomatoes). Both arrangements follow every rule.","accepted_summary":"Two valid layouts: T-H-E-B-S or S-T-H-E-B (plots 1→5)."}'::jsonb, '{"author_checked":true,"independent_review":{"status":"pending","reviewer":null,"date":null},"notes":"Solution set confirmed by enumeration of all 3,125 field combinations."}'::jsonb, '{"final_answer":{"fields":{"p1":"tomatoes","p2":"beans","p3":"herbs","p4":"empty","p5":"squash"}},"concise_explanation":"Squash goes in plot 5 because it must be at an end. Herbs then empty must be a pair, so herbs in plot 3 and empty in plot 4. Tomatoes must come before herbs, so tomatoes go in plot 1 and beans in plot 2.","stated_alternatives":[],"stated_assumptions":["Plot 1 is nearest the gate."],"cited_constraint_ids":["SQUASH-END","HERBS-THEN-EMPTY","TOMATO-BEFORE-HERBS"],"uncertainty_notes":""}'::jsonb) on conflict (problem_version_id) do nothing;
insert into problem_versions (id, family_id, slug, version, variant, category, difficulty, est_minutes, title, public_payload, provenance, content_hash) values ('logic.relay@1', 'logic.relay', 'relay-order', '1', 'standard', 'logic', 'easy', '5', 'Charity relay order', '{"summary":"Four runners, four legs, three rules. Find a running order that works.","statement":"Four friends — Ana, Ben, Cy, and Dee — are running a four-leg charity relay. Each person runs exactly one leg. Choose a running order for legs 1 to 4 that follows every rule. There may be more than one valid order; any order that follows all the rules is accepted.","facts":["Leg 1 starts at the park gate and leg 4 finishes at the stadium.","Cy is recovering from a sprained ankle and wants a middle leg on flat ground."],"constraints":[{"id":"ONE-LEG-EACH","text":"Each runner runs exactly one leg.","kind":"rule"},{"id":"CY-MIDDLE","text":"Cy runs neither the first nor the last leg.","kind":"rule"},{"id":"ANA-BEFORE-BEN","text":"Ana runs an earlier leg than Ben.","kind":"rule"},{"id":"DEE-NOT-NEXT-TO-CY","text":"Dee''s leg is not directly before or directly after Cy''s leg.","kind":"rule"}],"answer_format":{"kind":"choice_fields","instructions":"Choose who runs each leg.","fields":[{"id":"leg1","label":"Leg 1","options":[{"id":"ana","label":"Ana"},{"id":"ben","label":"Ben"},{"id":"cy","label":"Cy"},{"id":"dee","label":"Dee"}]},{"id":"leg2","label":"Leg 2","options":[{"id":"ana","label":"Ana"},{"id":"ben","label":"Ben"},{"id":"cy","label":"Cy"},{"id":"dee","label":"Dee"}]},{"id":"leg3","label":"Leg 3","options":[{"id":"ana","label":"Ana"},{"id":"ben","label":"Ben"},{"id":"cy","label":"Cy"},{"id":"dee","label":"Dee"}]},{"id":"leg4","label":"Leg 4","options":[{"id":"ana","label":"Ana"},{"id":"ben","label":"Ben"},{"id":"cy","label":"Cy"},{"id":"dee","label":"Dee"}]}]},"explanation_prompt":"Where did you start? Did you notice whether more than one order works?"}'::jsonb, '{"author":"Reasoning Lab project team","created":"2026-10-16","license":"MIT","origin":"original","fictional_data":true,"contamination_note":"Original task with two valid answers; ordering puzzles of this shape are common online."}'::jsonb, '88fd01f7103dde84ed44c992b7a8a1f96efa1d7740c5807bfd614133e46752dc') on conflict (id) do nothing;
insert into problem_keys (problem_version_id, validator, validator_version, rubric, rubric_version, reviewed_explanation, review, reference_output) values ('logic.relay@1', '{"engine":"rules","attributes":{},"rules":[{"type":"all_fields_answered","constraint_id":"ONE-LEG-EACH"},{"type":"distinct","constraint_id":"ONE-LEG-EACH"},{"type":"value_not_in_fields","constraint_id":"CY-MIDDLE","value":"cy","fields":["leg1","leg4"]},{"type":"before","constraint_id":"ANA-BEFORE-BEN","a":"ana","b":"ben","slots":["leg1","leg2","leg3","leg4"]},{"type":"not_adjacent","constraint_id":"DEE-NOT-NEXT-TO-CY","a":"dee","b":"cy","slots":["leg1","leg2","leg3","leg4"]}],"expected_solutions":[{"fields":{"leg1":"ana","leg2":"cy","leg3":"ben","leg4":"dee"}},{"fields":{"leg1":"dee","leg2":"ana","leg3":"cy","leg4":"ben"}}],"preferences":[]}'::jsonb, 'logic.relay@1/v1', '{"version":"rubric-2026-10-a","dimensions":["constraints","alternatives","assumptions"],"constraint_cues":{"ONE-LEG-EACH":["one leg","each runner","exactly one"],"CY-MIDDLE":["cy can''t","cy cannot","cy runs leg 2","cy runs leg 3","middle","not first or last","leg 2 or 3","leg 2 or leg 3"],"ANA-BEFORE-BEN":["ana before ben","ana earlier","before ben","ana runs before"],"DEE-NOT-NEXT-TO-CY":["next to cy","beside cy","adjacent","dee can''t","dee cannot","directly before","directly after"]},"edge_case_cues":[],"trade_off_cues":[],"anchors":{"alternatives":"Stating that a second valid order exists counts as an explicit alternative."}}'::jsonb, 'rubric-2026-10-a', '{"text":"Cy must run leg 2 or leg 3. If Cy runs leg 2, Dee cannot run legs 1 or 3, so Dee runs leg 4; Ana and Ben fill legs 1 and 3 with Ana first: Ana, Cy, Ben, Dee. If Cy runs leg 3, Dee cannot run legs 2 or 4, so Dee runs leg 1; Ana and Ben fill legs 2 and 4: Dee, Ana, Cy, Ben. Both orders follow every rule.","accepted_summary":"Two valid orders: Ana–Cy–Ben–Dee or Dee–Ana–Cy–Ben."}'::jsonb, '{"author_checked":true,"independent_review":{"status":"pending","reviewer":null,"date":null},"notes":"Two solutions by design, to test that valid alternative answers are accepted."}'::jsonb, '{"final_answer":{"fields":{"leg1":"ana","leg2":"cy","leg3":"ben","leg4":"dee"}},"concise_explanation":"Cy runs leg 2 or leg 3. With Cy on leg 2, Dee cannot be next to Cy, so Dee runs leg 4, and Ana before Ben gives Ana on leg 1 and Ben on leg 3.","stated_alternatives":["Putting Cy on leg 3 gives a second valid order: Dee, Ana, Cy, Ben."],"stated_assumptions":[],"cited_constraint_ids":["CY-MIDDLE","DEE-NOT-NEXT-TO-CY","ANA-BEFORE-BEN"],"uncertainty_notes":"Two orders are valid; I chose the first."}'::jsonb) on conflict (problem_version_id) do nothing;
insert into problem_versions (id, family_id, slug, version, variant, category, difficulty, est_minutes, title, public_payload, provenance, content_hash) values ('logic.study-room@1', 'logic.study-room', 'study-room-week', '1', 'standard', 'logic', 'easy', '4', 'Study room week', '{"summary":"Three clubs share one study room across three days. Find a schedule that follows every rule.","statement":"The Maple Harbor library has one bookable study room. Three student clubs — Robotics, Chess, and Poetry — each need it for one afternoon this week. The room is free on Monday, Tuesday, and Wednesday. Assign each club to a day so that every rule below is followed.","facts":["The room is available Monday, Tuesday, and Wednesday afternoons only.","The Robotics mentor works at another site on Mondays."],"constraints":[{"id":"ONE-EACH","text":"Each club gets exactly one day, and each day hosts exactly one club.","kind":"rule"},{"id":"ROBOTICS-NOT-MON","text":"Robotics cannot meet on Monday.","kind":"rule"},{"id":"CHESS-BEFORE-POETRY","text":"Chess must meet on an earlier day than Poetry.","kind":"rule"},{"id":"POETRY-NOT-WED","text":"Poetry cannot meet on Wednesday.","kind":"rule"}],"answer_format":{"kind":"choice_fields","instructions":"Choose which club uses the room on each day.","fields":[{"id":"mon","label":"Monday","options":[{"id":"robotics","label":"Robotics"},{"id":"chess","label":"Chess"},{"id":"poetry","label":"Poetry"}]},{"id":"tue","label":"Tuesday","options":[{"id":"robotics","label":"Robotics"},{"id":"chess","label":"Chess"},{"id":"poetry","label":"Poetry"}]},{"id":"wed","label":"Wednesday","options":[{"id":"robotics","label":"Robotics"},{"id":"chess","label":"Chess"},{"id":"poetry","label":"Poetry"}]}]},"explanation_prompt":"How did you narrow down the days? Which rule did you use first?"}'::jsonb, '{"author":"Reasoning Lab project team","created":"2026-10-16","license":"MIT","origin":"original","fictional_data":true,"contamination_note":"Original task. Its structure resembles common scheduling logic puzzles, so a model may have seen similar patterns."}'::jsonb, '79be5e09e7faa3c6a0d239df09bec1c04d68d14ebf91ed603fa1b25ef59ccdc4') on conflict (id) do nothing;
insert into problem_keys (problem_version_id, validator, validator_version, rubric, rubric_version, reviewed_explanation, review, reference_output) values ('logic.study-room@1', '{"engine":"rules","attributes":{},"rules":[{"type":"all_fields_answered","constraint_id":"ONE-EACH"},{"type":"distinct","constraint_id":"ONE-EACH"},{"type":"value_not_in_fields","constraint_id":"ROBOTICS-NOT-MON","value":"robotics","fields":["mon"]},{"type":"before","constraint_id":"CHESS-BEFORE-POETRY","a":"chess","b":"poetry","slots":["mon","tue","wed"]},{"type":"value_not_in_fields","constraint_id":"POETRY-NOT-WED","value":"poetry","fields":["wed"]}],"expected_solutions":[{"fields":{"mon":"chess","tue":"poetry","wed":"robotics"}}],"preferences":[]}'::jsonb, 'logic.study-room@1/v1', '{"version":"rubric-2026-10-a","dimensions":["constraints","alternatives","assumptions"],"constraint_cues":{"ONE-EACH":["one day each","each club","one club","exactly one","each day"],"ROBOTICS-NOT-MON":["robotics can''t","robotics cannot","robotics not","not monday","mentor"],"CHESS-BEFORE-POETRY":["before poetry","earlier than poetry","chess before","chess earlier","chess first"],"POETRY-NOT-WED":["poetry can''t","poetry cannot","not wednesday","poetry not","poetry isn''t"]},"edge_case_cues":[],"trade_off_cues":[],"anchors":{"constraints":"0 = not stated; 1 = rule mentioned; 2 = rule applied to eliminate a placement"}}'::jsonb, 'rubric-2026-10-a', '{"text":"Poetry cannot be on Wednesday, and Chess must come before Poetry, so Poetry cannot be on Monday either (nothing would be earlier). Poetry is therefore on Tuesday and Chess on Monday. That leaves Wednesday for Robotics, which also respects the no-Monday rule. This is the only schedule that follows every rule.","accepted_summary":"Monday Chess, Tuesday Poetry, Wednesday Robotics (unique)."}'::jsonb, '{"author_checked":true,"independent_review":{"status":"pending","reviewer":null,"date":null},"notes":"Uniqueness confirmed by bounded enumeration in tests/unit/seeds.test.ts."}'::jsonb, '{"final_answer":{"fields":{"mon":"chess","tue":"poetry","wed":"robotics"}},"concise_explanation":"Poetry cannot be on Wednesday, and Chess must come before Poetry, so Poetry cannot be on Monday. Poetry goes on Tuesday and Chess on Monday. Robotics takes Wednesday, which also avoids Monday.","stated_alternatives":[],"stated_assumptions":["Each club needs exactly one afternoon."],"cited_constraint_ids":["ONE-EACH","ROBOTICS-NOT-MON","CHESS-BEFORE-POETRY","POETRY-NOT-WED"],"uncertainty_notes":"None; the rules leave one schedule."}'::jsonb) on conflict (problem_version_id) do nothing;
